import Foundation
import Testing

@testable import ExperimentKit

/// Auto-generated promptIDs must be identical on both engines.
///
/// Paired statistics key on `promptID`, so a divergence here does not fail a
/// join — it joins the WRONG items. Until 2026-07-26 Python used the 0-based
/// FILE LINE index (blank lines included) while Swift used the 1-based
/// ordinal of parsed prompts, so for a file whose rows carry no explicit `id`
/// the engines produced `prompt-0…N-1` and `prompt-1…N`: the intersection
/// mapped one engine's item k+1 onto the other's item k and dropped one at
/// each end.
struct AutoPromptIDTests {

    @Test func idsCountParsedPromptsNotFileLines() throws {
        // The blank line must not consume an ordinal — that dependence on
        // whitespace is what made the two engines disagree.
        let jsonl = """
            {"text": "first"}

            {"text": "second"}
            """
        let prompts = try ExperimentTasks.parseTaskPrompts(Data(jsonl.utf8))
        #expect(prompts.map(\.id) == ["prompt-1", "prompt-2"])
    }

    @Test func anExplicitIDDoesNotShiftTheOnesAfterIt() throws {
        // The ordinal counts POSITION, so a named row still occupies one.
        let jsonl = """
            {"text": "a"}
            {"id": "named", "text": "b"}
            {"text": "c"}
            """
        let prompts = try ExperimentTasks.parseTaskPrompts(Data(jsonl.utf8))
        #expect(prompts.map(\.id) == ["prompt-1", "named", "prompt-3"])
    }

    /// Generated by the Python twin; regenerate with
    /// `scripts/regenerate-cross-engine-fixtures.py`.
    @Test func theRuleMatchesThePythonTwin() throws {
        let url = CodeResources.compiledCheckoutPath.appending(
            components: "Tests", "Fixtures", "cross-engine",
            "auto-prompt-ids.json")
        let fixture = try #require(
            try JSONSerialization.jsonObject(with: try Data(contentsOf: url))
                as? [String: Any])
        let lines = try #require(fixture["lines"] as? [String])
        let expected = try #require(fixture["ids"] as? [String])
        let prompts = try ExperimentTasks.parseTaskPrompts(
            Data(lines.joined(separator: "\n").utf8))
        #expect(
            prompts.map(\.id) == expected,
            "auto promptID drift — paired statistics would join the wrong items")
    }
}
